(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.01-t*0.15)*8 + Math.cos((y+w1y)*0.012+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.01+t*0.12)*8 + Math.sin((x+w1x)*0.013-t*0.2)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [200+Math.sin(t*0.45+1.5)*60, 40+Math.cos(t*0.65+2.5)*40, 0.14, 1.3],
    [400+Math.cos(t*0.55+3)*70, 120+Math.sin(t*0.75+1)*50, 0.05, 2.8],
    [80+Math.sin(t*0.7+0.5)*50, 100+Math.cos(t*0.5+3.5)*60, 0.11, 1.6],
    [300+Math.cos(t*0.25+4.5)*80, 200+Math.sin(t*0.45+2)*40, 0.09, 2.1]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.cos(d*f*0.5 - t*sp*0.4 + 3.0) * 0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, harm = hS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3
    + Math.sin(dist*0.08-ang*2+t*0.9)*0.15 + Math.cos(dist*0.03+ang*5-t*0.7)*0.1;
  const feed = Math.sin(act*1.5 + inh*0.8 + t*0.3) * 0.2;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + harm*0.4 + feed)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.6 + cell*0.2 + micro*0.05 + harm*0.15;
  const v = blend*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[15,70,110],[20,120,130],[45,155,120],[140,175,80],[200,170,55],[210,130,60],[185,85,65],[140,50,70],[80,25,55],[30,15,50],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.12:(Math.abs(reaction)<0.15?0.92:1.0);
  const shimmer = 1.0+Math.sin(sx*0.2+sy*0.15+t*4)*0.03*Math.abs(reaction);
  const m = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
